-- Contas dos serralheiros que ainda não existem: número de operador aleatório de 4 dígitos
-- (livre), sem palavra-passe nem acesso até o ADMIN a definir na ficha da pessoa.
do $$ declare r record; c text; begin
  for r in select distinct nome from _ri n where not exists (select 1 from "Users" u where lower(u."Name") = lower(n.nome)) loop
    loop
      c := lpad((1000 + floor(random() * 9000))::int::text, 4, '0');
      exit when not exists (select 1 from "Users" where "OperatorId" = c);
    end loop;
    insert into "Users"("Id","Name","OperatorId","ProviderUserId","RequiresPasswordChange","IsStandBy","CreatedAt","SessionVersion")
    values (gen_random_uuid(), r.nome, c, 'importacao-' || gen_random_uuid()::text, true, false, now(), 0);
  end loop;
end $$;
create temp table _ri2 as
select r.*, m."Id" as maq, u."Id" as uid,
  j.id as jobon, case when r.tipo = 'CM' then j.cm else j.mf end as ctx
from _ri r
join "Machines" m on m."Code" = r.linha
left join "Users" u on lower(u."Name") = lower(r.nome)
left join lateral (
  select jo."Id" as id, c."Id" as cm, f."Id" as mf from "JobOns" jo
  left join "CmContexts" c on c."JobOnId" = jo."Id"
  left join "MfContexts" f on f."JobOnId" = jo."Id"
  where jo."MachineId" = m."Id" and jo."InicioEm" <= r.dia and (jo."FimEm" is null or jo."FimEm" >= r.dia)
    and case when r.tipo = 'CM' then c."Id" else f."Id" end is not null
  order by jo."Id" desc limit 1) j on true;
do $$ declare s int; l int; n text; begin
  select count(*) filter (where jobon is not null), count(*) filter (where jobon is null) into s, l from _ri2;
  raise notice 'Com Job On: %, sem Job On (ver nota): %', s, l;
  select string_agg(distinct nome, ', ') into n from _ri2 where uid is null;
  if n is not null then raise notice 'Serralheiros sem utilizador (ficam sem «Quem»): %', n; end if;
end $$;
insert into "ReparacoesInternas"("JobOnId","MachineId","Tipo","Trabalho","CmContextId","MfContextId","Numero","RegistadoPorUserId","RegistadoEmUtc","DiaOperacional")
select jobon, maq, case when tipo = 'CM' then 1 else 2 end, 1,
  case when tipo = 'CM' then ctx end, case when tipo = 'MF' then ctx end,
  numero, uid, dia + time '12:00:00.000123', dia
from _ri2 where jobon is not null;

commit;
